
(function(root,factory){const api=factory(typeof module==='object'&&module.exports?require('./catalog.js'):root.EmberCatalog);if(typeof module==='object'&&module.exports)module.exports=api;else root.EmberFormat=api})(typeof window==='object'?window:globalThis,(catalog)=>{
function validateEffect(e,extended){if(!e||!(extended?catalog.presets.map(p=>p.id):['cosmic','fire','magic','smoke','snow','ember']).includes(e.id))throw Error('Invalid effect preset');for(const[k,min,max]of [['amount',5,200],['size',1,30],['speed',1,100],['spread',5,100],['life',1,8]])if(!Number.isFinite(e[k])||e[k]<min||e[k]>max)throw Error('Invalid '+k);if(!/^#[0-9a-f]{6}$/i.test(e.color)||!['continuous','burst'].includes(e.mode)||typeof e.glow!=='boolean'||typeof e.trail!=='boolean')throw Error('Invalid effect behavior');if(extended){(typeof module==='object'&&module.exports?require('./animation.js'):globalThis.EmberAnimation).validate(e.animation);if(e.motion!==undefined&&!['preset','aimed','orbit'].includes(e.motion))throw Error('Invalid motion');for(const [key,min,max]of [['trailLength',.1,10],['radiusVariation',0,100],['emitScaleX',.1,10],['emitScaleY',.1,10],['emitScaleZ',.1,10],['spinVariation',0,100],['directionRandom',0,180],['spriteRotationRandom',0,180],['velocityYaw',-180,180],['velocityPitch',-90,90],['ringSpin',-360,360]])if(e[key]!==undefined&&(!Number.isFinite(e[key])||e[key]<min||e[key]>max))throw Error('Invalid '+key);for(const key of ['positionX','positionY','positionZ'])if(e[key]!==undefined&&(!Number.isFinite(e[key])||Math.abs(e[key])>10000))throw Error('Invalid '+key);if(!['point','sphere','cone','ring','box'].includes(e.shape)||!['soft','star','square','diamond','ring'].includes(e.sprite)||typeof e.bounce!=='boolean')throw Error('Invalid particle shape');for(const[k,min,max]of [['gravity',-100,100],['turbulence',0,100],['endSize',0,5],['endOpacity',0,1]])if(!Number.isFinite(e[k])||e[k]<min||e[k]>max)throw Error('Invalid '+k);}}
function validateProject(data){if(!data||data.format!=='ember-vfx'||![1,2].includes(data.version)||typeof data.name!=='string'||data.name.length>100)throw Error('Invalid Ember project');validateEffect(data.effect,data.version===2);if(data.version===2){if(!Array.isArray(data.layers)||data.layers.length<1||data.layers.length>8)throw Error('Use one to eight particle layers');for(const layer of data.layers){if(typeof layer.name!=='string'||layer.name.length>100||typeof layer.enabled!=='boolean')throw Error('Invalid layer');validateEffect(layer.effect,true);}}return data}return {validateProject};});
